package com.seminarhub.domain.seminar.service;
import com.seminarhub.domain.member.domain.Member; import com.seminarhub.domain.seminar.domain.MemberSeminar; import com.seminarhub.domain.seminar.domain.Seminar; import com.seminarhub.domain.seminar.repository.MemberSeminarRepository; import com.seminarhub.global.dto.CursorRequest;
import java.util.List; import java.util.Optional; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class MemberSeminarService { private final MemberSeminarRepository repository;
@Transactional public MemberSeminar save(MemberSeminar e){return repository.save(e);} public Optional<MemberSeminar> findById(Long id){return repository.findByIdAndDeletedAtIsNull(id);} public List<MemberSeminar> findByIds(List<Long> ids){return repository.findAllByIdInAndDeletedAtIsNull(ids);} public List<MemberSeminar> findAll(MemberSeminarSearchQuery q){return repository.search(q);} public Page<MemberSeminar> findAll(MemberSeminarSearchQuery q,Pageable p){return repository.search(q,p);} public List<MemberSeminar> findByCursor(MemberSeminarSearchQuery q,CursorRequest c){return repository.search(q,c);} @Transactional public MemberSeminar update(MemberSeminar e,Member member,Seminar seminar){e.update(member,seminar);return e;} @Transactional public MemberSeminar delete(MemberSeminar e){e.delete();return e;} @Transactional public List<MemberSeminar> deleteAll(List<MemberSeminar> es){es.forEach(MemberSeminar::delete);return es;} }
